/* Browser-only sample export. This does not add an evidence-pack CLI command. */
(() => {
  'use strict';
  const BAKED_LOGO = 'data:image/png;base64,';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = (values, empty = 'Not supplied.') => values.length ? `<ul>${values.map(v => `<li>${esc(v)}</li>`).join('')}</ul>` : `<p>${esc(empty)}</p>`;
  const when = iso => {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return esc(iso);
    return esc(d.toLocaleString('en-GB', {day:'numeric', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit'}));
  };
  const logoMarkup = src => `<img class="pack-logo" src="${src || BAKED_LOGO}" width="155" height="44" alt="Zelto Pulse">`;

  function build(report, evidence, scenario, extras = {}) {
    const r = JSON.parse(JSON.stringify(report));
    const matchingSource = evidence?.provider === r.provider.id && evidence?.target === r.tenant.primaryIdentifier && evidence?.collectedAt === r.provider.collectedAt;
    const recommendations = r.remediationPlan.buckets.flatMap(bucket => bucket.items.map(item => ({...item, window: bucket.window})));
    return {
      sample: true,
      generatedAt: new Date().toISOString(),
      scenario,
      nis2: extras.nis2 || null,
      source: matchingSource ? evidence.source : 'No matching control snapshot',
      report: r,
      controls: (evidence?.controls || []).map(control => {
        const covered = r.coverage.collectors.some(c => c.collector === control.collector && c.status === 'success');
        return matchingSource && covered ? {...control} : {...control, status:'Not assessed', settings:null, note:'Matching, successfully collected evidence is not available.'};
      }),
      actions: r.findings.map(f => { const t = extras.trackOf ? extras.trackOf(f.id) : null; return {
        findingId:f.id, title:f.title,
        recommendation:recommendations.find(i => i.findingId === f.id)?.action || f.recommendation,
        window:recommendations.find(i => i.findingId === f.id)?.window || 'Not supplied',
        owner:t?.owner || 'Unassigned', status:t ? t.status : 'Recommended — no completion recorded', targetDate:t?.date || 'Not set', comments:t?.comments || '',
        reportedCompletion:'Not supplied', remediationEvidence:'Not supplied', verification:'Not verified',
        validationSteps:f.validationSteps || [],
      }; }),
    };
  }

  function plan(pack) {
    const titles = {
      nis2: 'NIS2 obligations by category',
      checked: 'What was checked',
      gaps: 'Gaps and unassessed areas',
      actions: 'How gaps were addressed',
      controls: 'Security controls and policies',
    };
    const ids = pack.nis2 ? ['nis2', 'checked', 'gaps', 'actions', 'controls'] : ['checked', 'gaps', 'actions', 'controls'];
    return ids.map((id, i) => ({id, title: titles[id], num: String(i + 1).padStart(2, '0')}));
  }

  function nis2Body(rows) {
    return `<p>Identity findings, action tracking and evidence items mapped to each NIS2 obligation.</p>
      ${rows.map(m => `<article class="pack-entry"><h3>${esc(m.ref)} · ${esc(m.name)}</h3><p class="pack-label">${esc(m.coverage)} · ${m.findings.length} related finding${m.findings.length === 1 ? '' : 's'}</p>
        ${m.findings.length ? `<div class="table-wrap"><table><thead><tr><th>Finding</th><th>Severity</th><th>Status</th><th>Owner</th><th>Target date</th></tr></thead><tbody>${m.findings.map(f => `<tr><td>${esc(f.id)} · ${esc(f.title)}</td><td>${esc(f.severity)}</td><td>${esc(f.status)}</td><td>${esc(f.owner || 'Unassigned')}</td><td>${esc(f.date || 'Not set')}</td></tr>`).join('')}</tbody></table></div>` : ''}
        ${m.evidence.length ? `<p><strong>Evidence items</strong></p><div class="table-wrap"><table><thead><tr><th>Item</th><th>Source</th><th>Status</th><th>Owner</th></tr></thead><tbody>${m.evidence.map(e => `<tr><td>${esc(e.label)}</td><td>${esc(e.source)}</td><td>${esc(e.status)}</td><td>${esc(e.owner || 'Unassigned')}</td></tr>`).join('')}</tbody></table></div>` : ''}</article>`).join('')}`;
  }

  function checkedBody(pack) {
    const r = pack.report, preview = Boolean(r.demo?.illustrative);
    return `<dl class="pack-facts"><div><dt>Provider</dt><dd>${esc(r.provider.displayName || r.provider.id)}</dd></div><div><dt>Environment</dt><dd>${esc(r.environment)} · synthetic</dd></div><div><dt>Assessment target</dt><dd>${esc(r.tenant.displayName || r.tenant.primaryIdentifier)}</dd></div><div><dt>Sample</dt><dd>${esc(pack.scenario)}</dd></div><div><dt>Posture score</dt><dd>${preview ? 'Not calculated · illustrative preview' : esc(r.score.overall) + ' / 100 · ' + esc(r.score.grade)}</dd></div></dl>
      <p>${preview ? 'Scope: fictional configuration and simulated collection outcomes below.' : 'Scope: configuration represented by the collectors below, evaluated with the current provider-specific rules.'}</p>
      <h3>${preview ? 'Illustrated areas' : 'Assessed categories'}</h3>${list(r.categories.filter(c => c.assessed).map(c => c.name))}
      <div class="table-wrap"><table><thead><tr><th>Collector</th><th>State</th><th>Resources</th><th>Required scopes</th></tr></thead><tbody>${r.coverage.collectors.map(c => `<tr><td>${esc(c.collector)}</td><td>${esc(c.status)}</td><td>${esc(c.count ?? 'Not supplied')}</td><td>${esc((c.requiredScopes || []).join(', ') || 'Not supplied')}</td></tr>`).join('')}</tbody></table></div>`;
  }

  function gapsBody(pack) {
    const r = pack.report, preview = Boolean(r.demo?.illustrative);
    const unassessed = r.categories.filter(c => !c.assessed).map(c => c.name);
    return `<p><strong>${r.findings.length} findings · ${r.coverage.partial ? 'partial coverage reported' : 'no collector gaps reported'}</strong></p>
      <h3>Unassessed categories</h3>${list(unassessed, 'None.')}
      <h3>Unsuccessful collectors</h3>${list(r.coverage.collectors.filter(c => c.status !== 'success').map(c => `${c.collector}: ${c.status}${c.notes ? ' — ' + c.notes : ''}`), 'None reported.')}
      <h3>Missing scopes</h3>${list(r.coverage.missingScopes, 'None reported.')}
      <h3>Assessment limitations</h3>${list(r.limitations)}
      <h3>Assumptions</h3>${list(r.assumptions || [])}
      ${r.findings.map(f => `<article class="pack-entry"><h3>${esc(f.title)}</h3><p class="pack-label">${esc(f.id)} · ${esc(f.severity)} · ${esc(f.classification)} · ${esc(f.confidence)} confidence</p><p><strong>${preview ? 'Illustrative evidence:' : 'Observed evidence:'}</strong> ${esc(f.evidence.summary)}</p><p><strong>Business risk:</strong> ${esc(f.businessRisk)}</p>${f.falsePositiveNotes.length ? `<p><strong>Context and exceptions</strong></p>${list(f.falsePositiveNotes)}` : ''}</article>`).join('') || '<p>No findings in this fixture.</p>'}`;
  }

  function actionsBody(pack) {
    return `<p>${pack.nis2 ? 'Owners, statuses and dates from the workspace.' : 'Recommended actions from this assessment.'}</p>
      ${pack.actions.map(a => `<article class="pack-entry"><h3>${esc(a.findingId)} · ${esc(a.title)}</h3><p><strong>Recommended action:</strong> ${esc(a.recommendation)}</p><p><strong>Suggested timing:</strong> ${esc(a.window)}</p><dl class="pack-facts"><div><dt>Owner</dt><dd>${esc(a.owner)}</dd></div><div><dt>Status</dt><dd>${esc(a.status)}</dd></div>${a.targetDate ? `<div><dt>Target date</dt><dd>${esc(a.targetDate)}</dd></div>` : ''}${a.comments ? `<div><dt>Comments</dt><dd>${esc(a.comments)}</dd></div>` : ''}<div><dt>Reported completion</dt><dd>${esc(a.reportedCompletion)}</dd></div><div><dt>Remediation evidence</dt><dd>${esc(a.remediationEvidence)}</dd></div><div><dt>Verification</dt><dd>${esc(a.verification)}</dd></div></dl><p><strong>Suggested validation steps</strong></p>${list(a.validationSteps, 'No rule-specific steps supplied; engineering review is required.')}</article>`).join('') || '<p>No finding-linked recommendations in this fixture.</p>'}`;
  }

  function controlsBody(pack) {
    const preview = Boolean(pack.report.demo?.illustrative);
    return `<p>${preview ? 'Hand-authored fictional settings for the provider preview.' : 'Observed settings from the matching synthetic snapshot.'}</p>
      ${pack.controls.map(c => `<article class="pack-entry"><h3>${esc(c.name)}</h3><p class="pack-label">${esc(c.status)}</p>${c.settings !== null ? `<pre>${esc(JSON.stringify(c.settings, null, 2))}</pre>` : '<p>No evidence available.</p>'}<p>${esc(c.note)}</p><p class="pack-provenance">Source field: ${esc(c.sourcePath)} · collector: ${esc(c.collector)}</p></article>`).join('')}`;
  }

  function bodies(pack) {
    return {
      nis2: () => nis2Body(pack.nis2 || []),
      checked: () => checkedBody(pack),
      gaps: () => gapsBody(pack),
      actions: () => actionsBody(pack),
      controls: () => controlsBody(pack),
    };
  }

  function toc(items) {
    return `<nav class="pack-toc" id="pack-contents" aria-label="Table of contents"><p class="eyebrow">Contents</p><ol>${items.map(s => `<li><a href="#pack-${s.id}"><span>${s.num}</span>${esc(s.title)}</a></li>`).join('')}</ol></nav>`;
  }

  function masthead(pack, assets, compact) {
    const r = pack.report, preview = Boolean(r.demo?.illustrative);
    const provider = r.provider.displayName || r.provider.id;
    if (compact) {
      return `<div class="pack-masthead">${logoMarkup(assets.logo)}<div><p class="eyebrow">NIS2 material</p><h2>Evidence pack</h2><p>${esc(provider)} · ${esc(pack.scenario)} · Prepared ${when(pack.generatedAt)}</p></div></div>`;
    }
    return `<header class="pack-cover"><p class="eyebrow">Identity security · NIS2 / KSC</p><h1>Evidence for <em>review</em>.</h1><p class="pack-lede">${preview ? 'Illustrative example for this provider.' : 'Identity-security findings, action plans and observed controls in one record.'}</p>
      <dl class="pack-facts"><div><dt>Provider</dt><dd>${esc(provider)}</dd></div><div><dt>Environment</dt><dd>${esc(r.environment)}</dd></div><div><dt>Sample</dt><dd>${esc(pack.scenario)}</dd></div><div><dt>Prepared</dt><dd>${when(pack.generatedAt)}</dd></div></dl></header>`;
  }

  function content(pack, compact = false, assets = {}) {
    const items = plan(pack);
    const htmlFor = bodies(pack);
    let markup = `<div class="pack-document">${masthead(pack, assets, compact)}${compact ? '' : toc(items)}${items.map(s => `<section class="pack-block" id="pack-${s.id}"><h2><span>${s.num}</span> ${esc(s.title)}</h2>${htmlFor[s.id]()}</section>`).join('')}</div>`;
    if (!compact) return markup;
    let index = 0;
    return markup.replace(/<section class="pack-block" id="([^"]+)"><h2>(.*?)<\/h2>/g, (_, id, title) => `<details class="pack-section" id="${id}" ${index++ === 0 ? 'open' : ''}><summary>${title}</summary><div>`).replace(/<\/section>/g, '</div></details>');
  }

  const exportStyles = `
:root{--primary:#7addc6;--secondary:#83219b;--accent:#e1f297;--canvas:#141429;--surface:#262659;--panel:#1c1c38;--raised:#222246;--ink:#f5f5fb;--muted:#b0b0c9;--line:#3b3b61}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;color:var(--ink);background:radial-gradient(ellipse at 85% 0,#33215055,transparent 42%),radial-gradient(ellipse at 8% 8%,#26265980,transparent 45%),var(--canvas);font:16px/1.65 Lato,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.skip{position:absolute;left:16px;top:-80px;z-index:20;padding:12px 16px;background:var(--primary);color:var(--canvas);border-radius:6px}
.skip:focus{top:12px}
.pack-top{max-width:1080px;margin:0 auto;padding:28px 40px 0;display:flex;align-items:center;justify-content:space-between;gap:16px}
.pack-top small{color:var(--muted);font-size:12px;letter-spacing:.12em;text-transform:uppercase}
main{max-width:1080px;margin:0 auto;padding:12px 40px 64px}
h1,h2,h3{margin:0;letter-spacing:-.03em}
h1{font-size:clamp(36px,5vw,56px);font-weight:900;letter-spacing:-.045em;line-height:1.08}
h1 em{font-style:normal;color:var(--primary)}
h2{font-size:26px;font-weight:900;margin:0 0 18px}
h2 span{color:var(--primary);font-size:13px;letter-spacing:.14em;margin-right:10px;font-weight:700;vertical-align:middle}
h3{font-size:17px;font-weight:700;margin:22px 0 8px}
p{margin:8px 0}
.eyebrow{font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:var(--primary);margin:0 0 14px}
.pack-logo{display:block;height:42px;width:auto;max-width:220px;object-fit:contain}
.pack-wordmark{font-size:22px;font-weight:900;letter-spacing:-.04em}
.pack-wordmark span{font-weight:400;color:var(--primary)}
.pack-cover{padding:36px 0 8px}
.pack-lede{font-size:18px;color:var(--muted);max-width:540px;margin:18px 0 28px;line-height:1.55}
.pack-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 28px;margin:0 0 8px}
.pack-facts dt{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.pack-facts dd{margin:4px 0 0;overflow-wrap:anywhere}
.pack-toc{margin:28px 0 8px;padding:24px 26px;border:1px solid #ffffff14;border-radius:18px;background:linear-gradient(145deg,#26265950,#17172d90)}
.pack-toc ol{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.pack-toc a{display:flex;gap:14px;align-items:baseline;padding:10px 4px;color:var(--ink);font-weight:700;text-decoration:none;border-radius:8px}
.pack-toc a:hover{color:var(--primary)}
.pack-toc a span{color:var(--primary);font-variant-numeric:tabular-nums;font-size:12px;letter-spacing:.08em;min-width:2em}
.pack-block{margin-top:40px;padding-top:28px;border-top:1px solid var(--line)}
.pack-entry{padding:16px 0;border-top:1px solid var(--line);break-inside:avoid}
.pack-label,.pack-provenance{font-size:13px;color:var(--muted);overflow-wrap:anywhere}
.pack-provenance{margin-top:12px}
table{width:100%;border-collapse:collapse;font-size:13px}
th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:700;background:var(--raised)}
td,th{padding:12px;border-bottom:1px solid var(--line);text-align:left;overflow-wrap:anywhere;vertical-align:top}
.table-wrap{overflow:auto;margin:12px 0;border:1px solid var(--line);border-radius:10px}
pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#101022;padding:16px;font-size:13px;border-radius:8px;border:1px solid var(--line)}
.pack-foot{max-width:1080px;margin:0 auto;padding:0 40px 48px;display:flex;justify-content:space-between;gap:16px;border-top:1px solid var(--line);padding-top:22px;color:var(--muted);font-size:12px}
.pack-foot a{color:var(--primary);text-decoration:none}
@media(max-width:700px){.pack-facts{grid-template-columns:1fr}.pack-top,main,.pack-foot{padding-left:20px;padding-right:20px}h1{font-size:34px}.pack-toc{padding:18px}}
@media print{body{background:#fff;color:#141429}.pack-toc a,.pack-foot a{color:inherit}h1 em,h2 span,.eyebrow,.pack-toc a span{color:#0f766e}.pack-cover,.pack-toc{break-after:avoid}.pack-entry{break-inside:avoid}.table-wrap{overflow:visible}a{color:inherit}}
`.replace(/\n/g, '');

  let brandCache = null;
  async function dataUri(path, mime) {
    try {
      const res = await fetch(path);
      if (!res.ok) return '';
      const buf = await res.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let binary = '';
      for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
      return `data:${mime};base64,${btoa(binary)}`;
    } catch {
      return '';
    }
  }
  async function brandAssets() {
    if (brandCache) return brandCache;
    const [regular, black] = await Promise.all([
      dataUri('Lato-Regular.woff2', 'font/woff2'),
      dataUri('Lato-Black.woff2', 'font/woff2'),
    ]);
    brandCache = {logo: BAKED_LOGO, regular, black};
    return brandCache;
  }

  async function html(pack) {
    const assets = await brandAssets();
    const fonts = [
      assets.regular ? `@font-face{font-family:Lato;src:url("${assets.regular}") format("woff2");font-weight:400;font-style:normal;font-display:swap}` : '',
      assets.black ? `@font-face{font-family:Lato;src:url("${assets.black}") format("woff2");font-weight:900;font-style:normal;font-display:swap}` : '',
    ].join('');
    const r = pack.report;
    const provider = r.provider.displayName || r.provider.id;
    return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#141429"><title>Zelto Pulse — NIS2 evidence pack</title><style>${fonts}${exportStyles}</style></head><body>
      <a class="skip" href="#pack-contents">Skip to contents</a>
      <div class="pack-top">${logoMarkup(assets.logo)}<small>Sample evidence pack</small></div>
      <main>${content(pack, false, assets)}</main>
      <footer class="pack-foot"><span>${esc(provider)} · ${esc(pack.scenario)}</span><span>Zelto Pulse</span></footer>
      <script>
        document.querySelectorAll('.pack-toc a').forEach(function(a){
          a.addEventListener('click', function(){
            var el = document.querySelector(a.getAttribute('href'));
            if (el) el.scrollIntoView({behavior:'smooth', block:'start'});
          });
        });
      <\/script>
    </body></html>`;
  }

  window.PulseEvidence = {build, content, html};
})();
